#!/usr/bin/env node
// Pack an example's resource tree into a Tension volume.
//
// Each example declares what to pack in its own `tension` block:
//
//   "tension": { "pack": { "input": "resources", "output": "build/assets.tns" } }
//
// and this is the one packer invocation. Most examples point it at a committed
// `resources/` tree; `examples/res` also declares generated files (an
// incompressible 20 MiB buffer that is too big to commit).
//
//   "generates": [
//     { "file": "data/large.bin", "size": 20971520, "pattern": "keystream",
//       "keep": "build/large.bin" },
//     { "file": "data/compressed.bin", "size": 2097152, "pattern": "zeros",
//       "keep": "build/compressed.bin" }
//   ]
//
// Generated bytes are a pure function of their offset, so the volume stays
// byte-reproducible from source and packing twice produces identical volumes.
//
// The tree that gets packed is assembled in a temporary directory rather than
// taken from the input directory directly, so a committed `assets/` is never
// written to. `keep` also leaves a copy under `build/`, which is what the res
// example's verifier compares the bytes read back out of the volume against.
//
// The packer itself is `tension-res`'s `zig build` artifact;
// `scripts/pack-volume.mjs` wraps it. This file exists so an example's pack step
// is data (the `tension` block) rather than a per-example shell script.
//
// Usage: node scripts/pack-example.mjs <example-dir>

import {
  closeSync, cpSync, existsSync, mkdirSync, mkdtempSync, openSync, readFileSync,
  rmSync, writeSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { run } from './lib/toolchain.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const exampleDir = resolve(process.argv[2] ?? process.cwd());
const pkgPath = join(exampleDir, 'package.json');

if (!existsSync(pkgPath)) {
  console.error(`pack-example: no package.json in ${exampleDir}`);
  process.exit(1);
}

const pkg = JSON.parse(readFileSync(pkgPath, 'utf8'));
const cfg = pkg.tension?.pack;
if (!cfg) {
  console.error(`pack-example: ${pkg.name} declares no 'tension.pack' block`);
  process.exit(1);
}

const input = join(exampleDir, cfg.input);
const output = join(exampleDir, cfg.output);
if (!existsSync(input)) {
  console.error(`pack-example: no input tree at ${input}`);
  process.exit(1);
}

// A staging copy: packing never writes into a committed tree.
const staging = mkdtempSync(join(tmpdir(), 'tension-pack-'));
const tree = join(staging, 'assets');
cpSync(input, tree, { recursive: true });

/// Write `size` bytes to `path` from a generator, one buffer at a time.
function generate(path, size, fill, chunk = 1 << 16) {
  mkdirSync(dirname(path), { recursive: true });
  const fd = openSync(path, 'w');
  try {
    let written = 0;
    while (written < size) {
      const n = Math.min(chunk, size - written);
      const buf = Buffer.allocUnsafe(n);
      fill(buf, n, written);
      writeSync(fd, buf);
      written += n;
    }
  } finally {
    closeSync(fd);
  }
}

for (const generated of cfg.generates ?? []) {
  // `keep` is where the example's verifier expects to find the bytes it will
  // compare against; the staged copy is what the packer sees.
  const kept = join(exampleDir, generated.keep ?? join('build', generated.file));
  const staged = join(tree, generated.file);

  if (generated.pattern === 'zeros') {
    generate(kept, generated.size, (buf) => buf.fill(0));
  } else if (generated.pattern === 'keystream') {
    // The demo's mixer, bit-exact. It must not compress: this File exists to
    // span more chunks than the runtime's per-open cache holds, and a repeating
    // pattern would collapse under the packer's compression threshold. Evaluated
    // at the *absolute* offset, because the guest checks pattern(offset) for the
    // real file offset.
    generate(kept, generated.size, (buf, n, base) => {
      for (let k = 0; k < n; k++) {
        let x = (((base + k) * 747796405 + 2891336453) >>> 0);
        x ^= x >>> 15;
        x = (x * 2246822519) >>> 0;
        x ^= x >>> 13;
        buf[k] = x & 0xff;
      }
    });
  } else {
    console.error(`pack-example: unknown generator pattern '${generated.pattern}'`);
    process.exit(1);
  }

  mkdirSync(dirname(staged), { recursive: true });
  cpSync(kept, staged);
  console.log(`pack-example: generated ${generated.file} (${generated.size} bytes, ` +
              `${generated.pattern}) -> ${generated.keep ?? generated.file}`);
}

run(process.execPath, [join(here, 'pack-volume.mjs'), tree, output]);
rmSync(staging, { recursive: true, force: true });
